const menuToggle = document.getElementById("menuToggle");
const primaryNav = document.getElementById("primaryNav");
const productKey = new URLSearchParams(window.location.search).get("product");
const product = Object.prototype.hasOwnProperty.call(products, productKey) ? products[productKey] : null;

document.getElementById("currentYear").textContent = String(new Date().getFullYear());
menuToggle.addEventListener("click", toggleNavigation);
primaryNav.addEventListener("click", function (event) {
    if (event.target.closest("a")) {
        closeNavigation();
    }
});
document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && menuToggle.getAttribute("aria-expanded") === "true") {
        closeNavigation();
        menuToggle.focus();
    }
});

if (product) {
    renderProduct(product);
} else {
    showProductNotFound();
}

/**
 * Renders the selected product content and prepares product-specific contact links.
 * @param {Object} productDetails Product content from the local product catalogue.
 */
function renderProduct(productDetails) {
    document.title = `${productDetails.name} | SG Softech`;
    document.querySelector('meta[name="description"]').content = productDetails.summary;
    document.getElementById("breadcrumbProduct").textContent = productDetails.name;
    document.getElementById("productCategory").textContent = productDetails.category;
    document.getElementById("productTitle").textContent = productDetails.name;
    document.getElementById("productSummary").textContent = productDetails.summary;
    document.getElementById("productOverview").textContent = productDetails.overview;
    document.getElementById("productFit").textContent =
        "Every organization has its own processes. We use these conversations to understand your priorities and agree which capabilities belong in the right-sized solution.";

    const image = document.getElementById("productImage");
    image.src = productDetails.image;
    image.alt = productDetails.imageAlt;

    const featureGrid = document.getElementById("product-features");
    productDetails.features.forEach(function (feature) {
        const card = document.createElement("article");
        const title = document.createElement("h3");
        const description = document.createElement("p");
        card.className = "product-feature";
        card.setAttribute("role", "listitem");
        title.textContent = feature[0];
        description.textContent = feature[1];
        card.append(title, description);
        featureGrid.append(card);
    });

    const fitList = document.getElementById("product-fit-list");
    productDetails.fit.forEach(function (item) {
        const listItem = document.createElement("li");
        listItem.textContent = item;
        fitList.append(listItem);
    });

    const demoMessage = `Hello SG Softech, I would like to request a demo of ${productDetails.name}. Please contact me to discuss a suitable time and my requirements.`;
    const demoHref = `https://wa.me/918669193952?${new URLSearchParams({ text: demoMessage })}`;
    document.querySelectorAll("[data-demo-link]").forEach(function (link) {
        link.href = demoHref;
    });

    const emailParameters = new URLSearchParams({
        subject: `Enquiry: ${productDetails.name}`,
        body: `Hello SG Softech,\n\nI have a question about ${productDetails.name}.`
    });
    document.querySelector("[data-product-email]").href =
        `mailto:sales@sgsoftech.in?${emailParameters}`;
}

/**
 * Shows a safe fallback when the requested product key is not recognized.
 */
function showProductNotFound() {
    document.title = "Product not found | SG Softech";
    document.querySelector("meta[name='description']").content =
        "Browse SG Softech products and software solutions.";
    document.querySelector("main").innerHTML =
        '<section class="section-wrap product-not-found"><p class="eyebrow">SG Softech solutions</p><h1>We could not find that product.</h1><p>Explore our products to find the right solution for your team.</p><a class="button button-primary" href="/index.html#solutions">Browse all solutions</a></section>';
}

/**
 * Toggles the compact product-page navigation and its accessible expanded state.
 */
function toggleNavigation() {
    const isOpen = menuToggle.getAttribute("aria-expanded") === "true";
    menuToggle.setAttribute("aria-expanded", String(!isOpen));
    menuToggle.setAttribute("aria-label", isOpen ? "Open navigation" : "Close navigation");
    primaryNav.classList.toggle("is-open", !isOpen);
}

/**
 * Closes the compact navigation after a link has been selected.
 */
function closeNavigation() {
    menuToggle.setAttribute("aria-expanded", "false");
    menuToggle.setAttribute("aria-label", "Open navigation");
    primaryNav.classList.remove("is-open");
}
